package com.myassist.assistant.network;
import org.json.JSONObject; import okhttp3.MediaType; import okhttp3.Request; import okhttp3.RequestBody; import okhttp3.Response;
public final class ApiService {private static final MediaType JSON=MediaType.get("application/json; charset=utf-8"); public interface Parser<T>{T parse(JSONObject b)throws Exception;} public interface Callback<T>{void onSuccess(T v);void onError(ApiClient.ApiException e);} public static <T> void run(Request q,Parser<T> p,Callback<T> cb){new Thread(()->{try(Response r=ApiClient.http().newCall(q).execute()){String raw=r.body()==null?"":r.body().string();JSONObject b=raw.isEmpty()?new JSONObject():new JSONObject(raw);if(!r.isSuccessful()){JSONObject er=b.optJSONObject("error");String m=er==null?null:er.optString("message",null);if(m==null)m=r.code()==401?"Session expired. Please log in again.":r.code()==409?"Conflict — the job changed.":"Request failed.";cb.onError(new ApiClient.ApiException(r.code(),m));return;}cb.onSuccess(p.parse(b));}catch(Exception e){cb.onError(new ApiClient.ApiException(0,"No internet connection. Check your network and try again."));}}).start();} public static Request get(String p){return new Request.Builder().url(ApiClient.BASE_URL+p).get().build();} public static Request post(String p,JSONObject j){return new Request.Builder().url(ApiClient.BASE_URL+p).post(RequestBody.create(j.toString(),JSON)).build();}}